import {reportLanguages,languageName,normalizeLanguage} from './languages.js';
import {t,preferences} from './i18n.js';
import {h,options} from './ui.js';
export function languageField(id,value,sample=false){const values=sample?Object.fromEntries(['en','hi','te'].map(c=>[c,languageName(c,preferences.language)])):reportLanguages(preferences.language);if(!sample&&normalizeLanguage(value))values[value]??=languageName(value,preferences.language);return `<div class="field language-field"><label for="${id}">${h(t('reportLanguage'))}</label><select id="${id}">${options(values,value)}</select>${sample?`<small>${h(t('sampleLanguages'))}</small>`:`<button type="button" class="language-browse" data-language-picker="${id}">${h(t('browseLanguages'))} ↗</button>`}</div>`;}
export function bindLanguagePickers(){document.querySelectorAll('[data-language-picker]').forEach(button=>button.onclick=()=>{
 const select=document.getElementById(button.dataset.languagePicker),previous=document.activeElement,dialog=document.createElement('dialog');dialog.className='confirm-dialog language-dialog';
 dialog.innerHTML=`<h2>${h(t('browseLanguages'))}</h2><p class="fine">${h(t('languageHelp'))}</p><label for="language-search">${h(t('languageSearch'))}</label><input id="language-search" type="search" autocomplete="off"><div id="language-options" class="language-options"></div><form id="custom-language"><label for="language-code">${h(t('languageCode'))}</label><input id="language-code" maxlength="35" placeholder="fr-CA" autocomplete="off"><button>${h(t('useLanguage'))}</button><p id="language-error" role="alert"></p></form><button id="close-languages" type="button">${h(t('cancel'))}</button>`;
 document.body.append(dialog);dialog.showModal();
 const close=()=>{dialog.close();dialog.remove();previous?.focus();};
 const choose=code=>{if(![...select.options].some(o=>o.value===code))select.add(new Option(languageName(code,preferences.language),code));select.value=code;close();select.dispatchEvent(new Event('change',{bubbles:true}));};
 const render=()=>{const query=dialog.querySelector('#language-search').value.trim().toLocaleLowerCase(preferences.language),list=dialog.querySelector('#language-options');list.innerHTML=Object.entries(reportLanguages(preferences.language)).filter(([code,name])=>[code,name,languageName(code,'en'),languageName(code,code)].some(v=>v.toLocaleLowerCase(preferences.language).includes(query))).map(([code,name])=>`<button type="button" data-code="${code}"><span>${h(name)}<small>${h(languageName(code,code))}</small></span><span>${code}</span></button>`).join('')||`<p>${h(t('noResults'))}</p>`;list.querySelectorAll('[data-code]').forEach(b=>b.onclick=()=>choose(b.dataset.code));};
 dialog.querySelector('#language-search').oninput=render;dialog.querySelector('#custom-language').onsubmit=e=>{e.preventDefault();const code=normalizeLanguage(dialog.querySelector('#language-code').value.trim());if(code)choose(code);else dialog.querySelector('#language-error').textContent=t('languageInvalid');};dialog.querySelector('#close-languages').onclick=close;dialog.oncancel=e=>{e.preventDefault();close();};render();dialog.querySelector('#language-search').focus();
 });}
